mapper.select:
/* com.buc.moa.user.mapper.UserMapper.existsByUsrId 아이디 중복체크 */
SELECT COUNT(*)
  FROM TB_USR
 WHERE USR_ID = #{usrId}

/* com.buc.moa.user.mapper.UserMapper.existsHpNo 휴대폰번호 중복확인 */
SELECT CASE WHEN COUNT(*) > 0 THEN TRUE
            ELSE FALSE
             END
  FROM TB_USR
 WHERE REGEXP_REPLACE(HP_NO, '[^0-9]', '', 'g') = #{hpNo}

/* com.buc.moa.user.mapper.UserMapper.selectUsrIdByHpNo 아이디 찾기 */
SELECT USR_ID
  FROM TB_USR
 WHERE REGEXP_REPLACE(HP_NO, '[^0-9]', '', 'g') = #{hpNo}
 LIMIT 1

mapper.insert:
/* com.buc.moa.user.mapper.UserMapper.insertUser 사용자정보 저장 */
INSERT INTO TB_USR
           (
             USR_ID            /* 사용자아이디 */
           , PWD               /* 비밀번호 */
           , USR_NM            /* 사용자명 */
           , NCK_NM            /* 닉네임 */
           , HP_NO             /* 전화번호 */
           , ADR               /* 주소 */
           , DTL_ADR           /* 상세주소 */
           , JOIN_DTM          /* 가입일시 */
           , ROL               /* 권한 */
           , FRST_REG_USER_ID  /* 최초등록사용자아이디 */
           , FRST_REG_DTM      /* 최초등록일시 */
           , LAST_MOD_USER_ID  /* 최종수정사용자아이디 */
           , LAST_MOD_DTM      /* 최종수정일시 */
           )
VALUES     (
             #{usrId}
           , #{pwd}
           , #{usrNm}
           , #{nckNm}
           , #{hpNo}
           , #{adr}
           , #{dtlAdr}
           , CURRENT_TIMESTAMP
           , #{rol}
           , #{frstRegUserId}
           , TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
           , #{lastModUserId}
           , TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
           )

mapper.update:
UPDATE TB_USR
   SET PWD = #{pwd}, LAST_MOD_USER_ID = #{lastModUserId}, LAST_MOD_DTM = TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
 WHERE USR_ID = #{usrId}

UPDATE TB_USR
   SET PIN_PWD = NULL
     , LAST_MOD_USER_ID = #{lastModUserId}
     , LAST_MOD_DTM = TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
 WHERE USR_ID = #{usrId}

/* com.buc.moa.user.mapper.UserMapper.updatePinPassword PIN 비밀번호 등록 */
UPDATE TB_USR
   SET PIN_PWD = #{pinPwd}
     , LAST_MOD_USER_ID = #{lastModUserId}
     , LAST_MOD_DTM = TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
 WHERE USR_ID = #{usrId}

UPDATE TB_USR
   SET ADR = #{adr}, DTL_ADR = #{dtlAdr}, LAST_MOD_USER_ID = #{lastModUserId}, LAST_MOD_DTM = TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
 WHERE USR_ID = #{usrId}

UPDATE TB_USR
   SET NCK_NM = #{nckNm}
     , LAST_MOD_USER_ID = #{lastModUserId}
     , LAST_MOD_DTM = TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
 WHERE USR_ID = #{usrId}

UPDATE TB_USR
   SET PRFL_IMG_FIL_SEQ = #{prflImgFilSeq}, LAST_MOD_USER_ID = #{lastModUserId}, LAST_MOD_DTM = TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
 WHERE USR_ID = #{usrId}
